function update_ticket_status(frm, values) {
    Object.keys(values).forEach(fieldname => frm.set_value(fieldname, values[fieldname]));
    frm.save().then(() => {
        frappe.show_alert({ message: __('Ticket updated.'), indicator: 'green' });
    });
}

function close_ticket(frm) {


    frappe.prompt([
        { label: __('Closure Notes'), fieldname: 'closure_notes', fieldtype: 'Small Text', reqd: 1 }
    ], function(values) {
        frm.set_value('custom_ticket_status', 'Closed');
