   TECH PLANNING & MISSION
========================= */

function create_tech_planning(frm) {
    if (!validate_ticket_ready(frm)) return;

    let planning_doc = {
        doctype: 'Tech Planning',
        custom_service_ticket: frm.doc.name,
        custom_parent_customer: frm.doc.custom_customer,
        custom_branch: frm.doc.custom_client_branch,
        custom_asset: frm.doc.custom_target_equipment,
        custom_request_description: build_request_description(frm),
        custom_request_type: frm.doc.custom_request_type,
        custom_ticket_type: frm.doc.custom_ticket_type,
        custom_service_type: frm.doc.custom_service_type,
        custom_primary_contact: frm.doc.custom_primary_contact,
        custom_contact_name: frm.doc.custom_contact_name,
        custom_contact_phone: frm.doc.custom_contact_phone,
        custom_contact_email: frm.doc.custom_contact_email,
        custom_planning_status: 'Draft'
    };

    frappe.call({
        method: 'frappe.client.insert',
        args: { doc: planning_doc },
        callback: function(r) {
            if (!r.message) return;
            let planning_name = r.message.name;
            copy_planned_team_to_doc(frm, 'Tech Planning', planning_name, function() {
                frm.set_value('custom_primary_planning_ref', planning_name);
                frm.set_value('custom_planning_required', 1);
                frm.set_value('custom_planning_status', 'Required');
                frm.set_value('custom_ticket_status', 'Ready for Planning');
                frm.save().then(() => frappe.set_route('Form', 'Tech Planning', planning_name));
            });
        }
    });
}

function create_tech_mission(frm, planning_name) {
    if (!validate_ticket_ready(frm)) return;

    let mission_doc = {
        doctype: 'Tech Mission',
        custom_service_ticket: frm.doc.name,
        custom_tech_planning: planning_name || '',
        custom_parent_customer: frm.doc.custom_customer,
        custom_branch: frm.doc.custom_client_branch,
        custom_asset: frm.doc.custom_target_equipment,
        custom_ticket_type: frm.doc.custom_ticket_type || 'Service',
        custom_work_type: frm.doc.custom_work_type || 'Quick Intervention',
        custom_service_type: frm.doc.custom_service_type || 'Billable',
        custom_mission_status: 'Scheduled',
        custom_request_description: build_request_description(frm)
    };

    frappe.call({
        method: 'frappe.client.insert',
        args: { doc: mission_doc },
        callback: function(r) {
            if (!r.message) return;
            let mission_name = r.message.name;
            copy_planned_team_to_doc(frm, 'Tech Mission', mission_name, function() {
                frm.set_value('custom_primary_mission_ref', mission_name);
                frm.set_value('custom_ticket_status', 'Planned');
                if (planning_name) {
                    frm.set_value('custom_primary_planning_ref', planning_name);
                    frm.set_value('custom_planning_status', 'Fully Planned');
                } else {
                    frm.set_value('custom_planning_required', 0);
                    frm.set_value('custom_planning_status', 'Not Required');
                }

                frappe.call({
                    method: 'maintenance_app.api.create_todos_for_existing_mission',
                    args: { mission_name: mission_name },
                    callback: function() {
                        frm.save().then(() => frappe.set_route('Form', 'Tech Mission', mission_name));
                    }
                });
            });
        }
    });
}

