   SUPPORT FUNCTIONS
========================= */

function copy_planned_team_to_doc(frm, doctype, docname, callback) {
    let team = frm.doc.custom_planned_team || [];
    if (!team.length) { callback(); return; }

    frappe.call({
        method: 'frappe.client.get',
        args: { doctype: doctype, name: docname },
        callback: function(r) {
            if (!r.message) { callback(); return; }
            let target_doc = r.message;
            target_doc.custom_planned_team = team.map(row => ({
                doctype: 'Planned Technicians',
                custom_technician: row.custom_technician
            }));
            frappe.call({
                method: 'frappe.client.save',
                args: { doc: target_doc },
                callback: () => callback()
            });
        }
    });
}

function validate_ticket_ready(frm) {
    if (!frm.doc.custom_customer || !frm.doc.custom_client_branch || !frm.doc.custom_target_equipment) {
        frappe.msgprint(__('Please select Customer, Client Branch, and Target Equipment first.'));
        return false;
    }
    if (!frm.doc.custom_planned_team || !frm.doc.custom_planned_team.length) {
        frappe.msgprint(__('Please assign at least one technician in Planned Team before continuing.'));
        return false;
    }
    return true;
}

function build_request_description(frm) {
    let parts = [];
    if (frm.doc.custom_subject) parts.push('Subject: ' + frm.doc.custom_subject);
    if (frm.doc.custom_request_type) parts.push('Request Type: ' + frm.doc.custom_request_type);
    if (frm.doc.custom_ticket_type) parts.push('Ticket Type: ' + frm.doc.custom_ticket_type);
    if (frm.doc.custom_description) parts.push('Description:\n' + frm.doc.custom_description);
    return parts.join('\n\n');
}

function set_ticket_filters(frm) {
    frm.set_query('custom_client_branch', () => ({
        filters: [['Client Branch', 'custom_parent_customer', '=', frm.doc.custom_customer]]
    }));
    frm.set_query('custom_target_equipment', () => ({
        filters: [
            ['Installed Equipment', 'custom_parent_customer', '=', frm.doc.custom_customer],
            ['Installed Equipment', 'custom_branch', '=', frm.doc.custom_client_branch]
        ]
    }));
}

function find_active_contract(frm) {
    if (!frm.doc.custom_customer) return;
    frappe.call({
        method: 'frappe.client.get_list',
        args: {
            doctype: 'Maintenance Contract',
            filters: { custom_customer: frm.doc.custom_customer, custom_status: 'Active' },
            fields: ['name', 'custom_contract_type', 'custom_default_sla_rule', 'custom_start_date', 'custom_end_date']
        },
        callback: function(r) {
            let contracts = r.message || [];
            let today = frappe.datetime.get_today();
            contracts = contracts.filter(c => (!c.custom_start_date || c.custom_start_date <= today) && (!c.custom_end_date || c.custom_end_date >= today));
            if (!contracts.length) return;
            let contract = contracts[0];
            frm.set_value('custom_maintenance_contract', contract.name);
            if (contract.custom_default_sla_rule) frm.set_value('custom_sla_rule', contract.custom_default_sla_rule);
            frm.set_value('custom_service_type', contract.custom_contract_type === 'Warranty' ? 'Warranty' : (contract.custom_contract_type === 'AMC' ? 'AMC' : 'Billable'));
        }
    });
}

function toggle_rework_fields(frm) {
    let is_rework = frm.doc.custom_is_rework ? 1 : 0;
    ['custom_original_ticket', 'custom_rework_reason', 'custom_rework_approved', 'custom_rework_count'].forEach(f => {
        if (frm.fields_dict[f]) frm.set_df_property(f, 'hidden', !is_rework);
    });
}

function toggle_hold_reason(frm) {
    let on_hold = frm.doc.custom_ticket_status === 'On Hold';
    if (frm.fields_dict.custom_hold_reason) {
        frm.set_df_property('custom_hold_reason', 'hidden', !on_hold);
        frm.set_df_property('custom_hold_reason', 'reqd', on_hold);
    }
}

function show_ticket_status_banner(frm) {
    let ts = frm.doc.custom_ticket_status || 'Open';
    let cs = frm.doc.custom_commercial_status || 'N/A';
    frm.page.set_indicator(__('Ticket: {0}', [ts]), get_ticket_indicator(ts));
    $('.custom-commercial-indicator, .custom-hold-indicator').remove();
    let comm_html = `<span class="indicator-pill custom-commercial-indicator ${get_commercial_indicator(cs)}">Commercial: ${cs}</span>`;
    $(comm_html).insertAfter('.page-title .indicator-pill');
}

function get_ticket_indicator(s) {
    return { 'Open': 'gray', 'Under Review': 'yellow', 'Ready for Planning': 'blue', 'Planned': 'blue', 'In Progress': 'blue', 'On Hold': 'orange', 'Resolved': 'green', 'Closed': 'green', 'Cancelled': 'red' }[s] || 'gray';
}

function get_commercial_indicator(s) {
    return { 'N/A': 'gray', 'To Quote': 'purple', 'Quote Sent': 'purple', 'Quote Approved': 'blue', 'Awaiting Parts': 'red', 'Ready for Planning': 'blue', 'To be Invoiced': 'orange', 'Invoiced': 'green', 'Covered': 'green', 'Paid': 'green' }[s] || 'gray';
}

function create_rework_ticket(frm) {
    frappe.new_doc('Service Ticket', {
        custom_customer: frm.doc.custom_customer,
        custom_client_branch: frm.doc.custom_client_branch,
        custom_target_equipment: frm.doc.custom_target_equipment,
        custom_subject: 'Rework - ' + (frm.doc.custom_subject || frm.doc.name),
        custom_description: 'Rework for: ' + frm.doc.name,
        custom_is_rework: 1,
        custom_original_ticket: frm.doc.name
    });
}

function toggle_ticket_tabs(frm) {
    let status = frm.doc.custom_ticket_status || '';

    let show_resolution =
        status === 'Resolved' ||
        status === 'Closed';

    let show_rework = frm.doc.custom_is_rework ? true : false;

    let show_commercial =
        frm.doc.custom_quotation ||
        frm.doc.custom_sales_order ||
        frm.doc.custom_sales_invoice ||
        frm.doc.custom_billing_required ||
        frm.doc.custom_commercial_status;

    if (frm.fields_dict.custom_resolution_detail) {
        frm.toggle_display('custom_resolution_detail', show_resolution);
    }

    if (frm.fields_dict.custom_rework) {
        frm.toggle_display('custom_rework', show_rework);
    }

    if (frm.fields_dict.custom_status_commercial) {
        frm.toggle_display('custom_status_commercial', !!show_commercial);
    }

    frm.refresh_fields();
}

