function load_component_overview(frm) {
    if (!frm.fields_dict.custom_component_overview || frm.is_new()) {
        return;
    }

    frappe.call({
        method: "frappe.client.get_list",
        args: {
            doctype: "Installed Equipment",
            filters: {
                parent_maintenance_app_asset_registry: frm.doc.name
            },
            fields: [
                "name",
                "custom_asset_name",
                "custom_asset_status",
                "custom_equipment_health",
                "custom_asset_id"
            ],
            limit_page_length: 50
        },
        callback: function(r) {
            let rows = r.message || [];

            if (!rows.length) {
                frm.fields_dict.custom_component_overview.$wrapper.html(
                    "<div class='text-muted'>No components linked.</div>"
                );
                return;
            }

            let html = "<div class='list-group'>";

            rows.forEach(function(row) {
                html += `
                    <a class="list-group-item"
                       href="/app/installed-equipment/${row.name}">
                        <b>${row.custom_asset_name || row.name}</b><br>
                        <span class="text-muted">
                            Serial: ${row.custom_asset_id || "-"} |
                            Status: ${row.custom_asset_status || "-"} |
                            Health: ${row.custom_equipment_health || "-"}
                        </span>
                    </a>
                `;
            });

            html += "</div>";

            frm.fields_dict.custom_component_overview.$wrapper.html(html);
        }
    });
}

