function add_planning_buttons(frm) {
    frm.clear_custom_buttons();

    if (frm.is_new()) return;

    if (!frm.doc.custom_mission_ref) {
        frm.add_custom_button(__('Create Tech Mission'), function() {
            create_mission_from_planning(frm);
        }, __('Actions'));
    }

    if (frm.doc.custom_mission_ref) {
        frm.add_custom_button(__('Open Mission'), function() {
            frappe.set_route('Form', 'Tech Mission', frm.doc.custom_mission_ref);
        }, __('Actions'));
    }

    if (frm.doc.custom_mission_ref && frm.doc.custom_reschedule_required) {
        frm.add_custom_button(__('Replan Mission'), function() {
            replan_mission_from_planning(frm);
        }, __('Actions'));
    }
}

function create_mission_from_planning(frm) {
    if (!validate_planning(frm)) return;

    frappe.call({
        method: 'maintenance_app.api.create_mission_from_planning',
        args: {
            planning_name: frm.doc.name
        },
        freeze: true,
        freeze_message: __('Creating Tech Mission...'),
        callback: function(r) {
            if (!r.message) return;

            frappe.msgprint(__('Tech Mission created successfully.'));

            frm.reload_doc().then(function() {
                frappe.set_route('Form', 'Tech Mission', r.message.mission);
            });
        }
    });
}

function replan_mission_from_planning(frm) {
    if (!frm.doc.custom_mission_ref) {
        frappe.msgprint(__('No Tech Mission is linked to this planning.'));
        return;
    }

    if (!frm.doc.custom_reschedule_required) {
        frappe.msgprint(__('Please check Reschedule Required before replanning.'));
        return;
    }

    if (!frm.doc.custom_reschedule_reason) {
        frappe.msgprint(__('Please select a Reschedule Reason before replanning.'));
        return;
    }

    frappe.call({
        method: 'maintenance_app.api.replan_mission_from_planning',
        args: {
            planning_name: frm.doc.name
        },
        freeze: true,
        freeze_message: __('Updating Tech Mission and ToDos...'),
        callback: function(r) {
            if (!r.message) return;

            frappe.msgprint(__('Mission replanned successfully.'));
            frm.reload_doc();
        }
    });
}

function validate_planning(frm) {
    if (!frm.doc.custom_service_ticket) {
        frappe.msgprint(__('Service Ticket is required.'));
        return false;
    }

    if (!frm.doc.custom_parent_customer) {
        frappe.msgprint(__('Customer is required.'));
        return false;
    }

    if (!frm.doc.custom_branch) {
        frappe.msgprint(__('Client Branch is required.'));
        return false;
    }

    if (!frm.doc.custom_asset) {
        frappe.msgprint(__('Target Equipment is required.'));
        return false;
    }

    if (!frm.doc.custom_planned_starttime || !frm.doc.custom_planned_endtime) {
        frappe.msgprint(__('Planned Start Time and Planned End Time are required.'));
        return false;
    }

    if (!frm.doc.custom_planned_team || frm.doc.custom_planned_team.length === 0) {
        frappe.msgprint(__('Please add at least one technician in Planned Team.'));
        return false;
    }

    return true;
}

function toggle_reschedule_fields(frm) {
    let has_mission = !!frm.doc.custom_mission_ref;

    [
        'custom_reschedule_required',
        'custom_reschedule_reason',
        'custom_reschedule_notes',
        'custom_reschedule_count'
    ].forEach(function(fieldname) {
        if (frm.fields_dict[fieldname]) {
            frm.set_df_property(fieldname, 'hidden', has_mission ? 0 : 1);
        }
    });

    if (frm.fields_dict.custom_reschedule_reason) {
        frm.set_df_property(
            'custom_reschedule_reason',
            'reqd',
            frm.doc.custom_reschedule_required ? 1 : 0
        );
    }
}

