function setup_check_buttons(frm) {

    if (frm.is_new() || frm.doc.docstatus !== 0) {
        return;
    }

    frm.page.clear_primary_action();

    // BEFORE CHECK IN
    if (!frm.doc.custom_start_time) {

        frm.page.set_primary_action(__('Check In'), function() {

            frm.set_value(
                'custom_start_time',
                frappe.datetime.now_datetime()
            );

            frm.save().then(() => {

                frm.reload_doc().then(() => {

                    toggle_lock_state(frm);
                    toggle_intervention_fields(frm);
                    toggle_config_changes_access(frm);
                    setup_check_buttons(frm);

                    frappe.show_alert({
                        message: __('Checked In'),
                        indicator: 'green'
                    });

                });

            });

        });

        return;
    }

    // AFTER CHECK IN / BEFORE CHECK OUT
    if (
        frm.doc.custom_start_time &&
        !frm.doc.custom_end_time
    ) {

        frm.page.set_primary_action(__('Check Out'), function() {
            show_checkout_dialog(frm);
        });

        return;
    }

    // AFTER CHECK OUT
    if (
        frm.doc.custom_start_time &&
        frm.doc.custom_end_time
    ) {

        frm.page.set_primary_action(__('Submit'), function() {
            frm.savesubmit();
        });

    }
}
