function toggle_intervention_fields(frm) {

    let type = frm.doc.custom_intervention_type || '';
    let checked_in = !!frm.doc.custom_start_time;

    // HIDE / RESET EVERYTHING FIRST

    [
        'custom_destination_branch',
        'custom_swap_classification',
        'custom_removed_asset_outcome',
        'custom_new_make',
        'custom_loan_required',
        'custom_loan_approved',
        'custom_is_loan_return',
        'custom_replacement_serial',
        'custom_replacement_asset',
        'custom_new_model'
    ].forEach(function(fieldname) {

        if (frm.fields_dict[fieldname]) {

            frm.set_df_property(
                fieldname,
                'hidden',
                1
            );

            frm.set_df_property(
                fieldname,
                'reqd',
                0
            );
        }
    });

    // STOP BEFORE CHECK-IN

    if (!checked_in) {
        return;
    }

    // ASSET RELOCATION

    if (type === 'Asset Relocation') {

        frm.set_df_property(
            'custom_destination_branch',
            'hidden',
            0
        );
    }

    // SWAP

    if (type === 'Swap') {

        [
            'custom_swap_classification',
            'custom_removed_asset_outcome',
            'custom_replacement_asset',
            'custom_replacement_serial',
            'custom_new_make',
            'custom_new_model'
        ].forEach(function(fieldname) {

            if (frm.fields_dict[fieldname]) {

                frm.set_df_property(
                    fieldname,
                    'hidden',
                    0
                );
            }
        });
    }

    // LOAN

    if (type === 'Loan') {

        [
            'custom_swap_classification',
            'custom_removed_asset_outcome',
            'custom_loan_required',
            'custom_loan_approved',
            'custom_is_loan_return',
            'custom_replacement_asset'
        ].forEach(function(fieldname) {

            if (frm.fields_dict[fieldname]) {

                frm.set_df_property(
                    fieldname,
                    'hidden',
                    0
                );
            }
        });
    }

    // RETIREMENT / DISPOSAL

    if (
        type === 'Retirement' ||
        type === 'Disposal'
    ) {

        frm.set_df_property(
            'custom_removed_asset_outcome',
            'hidden',
            0
        );
    }
}

